{
  "name": "LegacyMigrationMap",
  "type": "object",
  "description": "Internal audit map for one-time legacy SignEstimate Pro migrations. Keeps source record IDs mapped to their CCS record IDs so migrations can be resumed safely without creating duplicates.",
  "properties": {
    "source_app_id": {
      "type": "string"
    },
    "source_entity": {
      "type": "string"
    },
    "source_id": {
      "type": "string"
    },
    "target_entity": {
      "type": "string"
    },
    "target_id": {
      "type": "string"
    },
    "source_created_date": {
      "type": "string"
    },
    "source_updated_date": {
      "type": "string"
    },
    "migration_batch": {
      "type": "string"
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "source_app_id",
    "source_entity",
    "source_id",
    "target_entity",
    "target_id"
  ],
  "rls": {
    "read": {
      "user_condition": {
        "role": "admin"
      }
    },
    "create": {
      "user_condition": {
        "role": "admin"
      }
    },
    "update": {
      "user_condition": {
        "role": "admin"
      }
    },
    "delete": {
      "user_condition": {
        "role": "admin"
      }
    }
  }
}

{
  "name": "Machine",
  "type": "object",
  "description": "Unified production machine registry for the estimator: one row per piece of equipment (roll-fed printer/cutter, sheet-fed press, or other production hardware). Carries run-cost economics (cost_per_hour, setup cost/time, disposable consumables), named speed/quality profiles, labor and margin hooks. Generalizes the narrower MachineRate pricing rows and the vinyl-specific VinylMachine records \u2014 those registries stay authoritative for their own modules; Machine is the cross-module catalog new estimating code should reference.",
  "properties": {
    "name": {
      "type": "string",
      "description": "Machine label, e.g. 'HP Latex 360', 'CNC Router Table A'."
    },
    "machine_type": {
      "type": "string",
      "description": "Feed/class of machine: 'roll_fed', 'sheet_fed', or 'other'. Stored as a free-form string so additional classes can be introduced without a schema migration."
    },
    "cost_per_hour": {
      "type": "number",
      "description": "Machine run cost in $ per runtime hour."
    },
    "profiles": {
      "type": "array",
      "description": "Named speed/quality profiles for this machine, e.g. draft / production / high_quality. Each entry: { name: string, speed_settings: object } where speed_settings holds machine-specific rate keys (sqft_per_hour, inches_per_second, pass_count, etc.).",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Profile label, e.g. 'draft', 'production', 'high_quality'."
          },
          "speed_settings": {
            "type": "object",
            "description": "Machine-specific speed/quality parameters for this profile; key set is module-defined.",
            "additionalProperties": true
          }
        },
        "additionalProperties": true
      }
    },
    "disposable_cost_per_unit": {
      "type": "number",
      "description": "Consumable/disposable cost per produced unit (blades, bits, ink allowance, etc.)."
    },
    "setup_cost": {
      "type": "number",
      "description": "Flat $ charged once per job for machine setup, in addition to any time-based setup billing."
    },
    "setup_minutes": {
      "type": "number",
      "description": "One-time setup minutes billed at the machine rate each time the machine is used."
    },
    "labor_pct": {
      "type": "number",
      "description": "Percent of machine run time that requires paid operator labor (0-100)."
    },
    "weighted_multiplier": {
      "type": "number",
      "description": "Complexity/difficulty weighting applied to this machine's computed cost before margin."
    },
    "margin_chart_id": {
      "type": "string",
      "description": "Optional reference to the margin/markup chart record used to price this machine's output."
    },
    "income_account": {
      "type": "string",
      "description": "Income account code/name this machine's revenue posts to (links into the accounting chart, e.g. an IncomeAccount row)."
    },
    "status": {
      "type": "string",
      "description": "Lifecycle status, e.g. 'active' or 'inactive'. Inactive machines are ignored by pricing."
    },
    "description": {
      "type": "string",
      "description": "Free-form notes about this machine (location, capabilities, constraints)."
    }
  },
  "rls": {
    "create": {
      "user_condition": {
        "role": "__machine_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__machine_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__machine_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__machine_backend_only__"
      }
    }
  }
}

{
  "name": "MachineRate",
  "type": "object",
  "properties": {
    "name": {
      "type": "string",
      "description": "Machine label, e.g. '54in Vinyl Plotter', 'CNC Router Table A'."
    },
    "machine_type": {
      "type": "string",
      "enum": [
        "vinyl",
        "cnc",
        "laser",
        "printer",
        "other"
      ],
      "description": "Equipment class this rate row prices."
    },
    "setup_minutes": {
      "type": "number",
      "default": 0,
      "description": "One-time setup minutes billed at the runtime rate each time the machine is used."
    },
    "runtime_rate_per_hour": {
      "type": "number",
      "description": "Machine rate in $ per runtime hour (also bills setup time)."
    },
    "maintenance_rate_per_hour": {
      "type": "number",
      "default": 0,
      "description": "Additional $ per runtime hour covering wear, blades/bits, and maintenance."
    },
    "material_waste_pct": {
      "type": "number",
      "default": 0,
      "description": "Percent of the job's material cost added to cover machine spoilage/waste."
    },
    "status": {
      "type": "string",
      "enum": [
        "active",
        "inactive"
      ],
      "default": "active",
      "description": "Inactive machine rows are ignored by the pricing engine."
    },
    "updated_by": {
      "type": "string",
      "description": "Email of the staff user who last saved this row (audit)."
    }
  },
  "required": [
    "name",
    "machine_type",
    "runtime_rate_per_hour"
  ],
  "rls": {
    "create": {
      "user_condition": {
        "role": "__machinerate_backend_only__"
      }
    },
    "read": {
      "user_condition": {
        "role": "__machinerate_backend_only__"
      }
    },
    "update": {
      "user_condition": {
        "role": "__machinerate_backend_only__"
      }
    },
    "delete": {
      "user_condition": {
        "role": "__machinerate_backend_only__"
      }
    }
  }
}

{
  "name": "MaintenanceActionRate",
  "type": "object",
  "description": "Per (sign-type \u00d7 action) rate matrix. One row per combination. Drives the Service Items / Labor calculations.",
  "properties": {
    "sign_type": {
      "type": "string",
      "enum": [
        "flush_channel",
        "halo_channel",
        "raceway_channel",
        "capsule_logo",
        "dimensional_letters",
        "monument_sign",
        "pylon_sign",
        "post_and_panel"
      ]
    },
    "action": {
      "type": "string",
      "enum": [
        "clean",
        "repaint",
        "led_retrofit",
        "replace_leds",
        "replace_power_supplies",
        "replace_fluorescent_tubes",
        "fix_electrical",
        "troubleshoot",
        "vinyl_replacement",
        "replace_face",
        "replace_returns",
        "replace_trim_cap",
        "reseal",
        "rewire",
        "replace_ballast",
        "replace_transformer",
        "replace_breaker",
        "replace_photocell",
        "replace_timer",
        "replace_disconnect"
      ]
    },
    "rate_basis": {
      "type": "string",
      "enum": [
        "per_letter",
        "per_cabinet",
        "per_unit",
        "per_sqft",
        "flat"
      ],
      "default": "per_letter",
      "description": "How the time scales. per_letter scales by qty_letters, per_cabinet/flat is a one-shot per service item, per_unit scales by quantity (e.g. LEDs being replaced), per_sqft scales by cabinet face area."
    },
    "base_minutes_xs": {
      "type": "number",
      "default": 0
    },
    "base_minutes_s": {
      "type": "number",
      "default": 0
    },
    "base_minutes_m": {
      "type": "number",
      "default": 0
    },
    "base_minutes_l": {
      "type": "number",
      "default": 0
    },
    "base_minutes_xl": {
      "type": "number",
      "default": 0
    },
    "base_minutes_xxl": {
      "type": "number",
      "default": 0
    },
    "base_minutes_cab_s": {
      "type": "number",
      "default": 0,
      "description": "Cabinet size: Small (\u2264 16 sqft)"
    },
    "base_minutes_cab_m": {
      "type": "number",
      "default": 0,
      "description": "Cabinet size: Medium (16\u201348 sqft)"
    },
    "base_minutes_cab_l": {
      "type": "number",
      "default": 0,
      "description": "Cabinet size: Large (48\u2013100 sqft)"
    },
    "base_minutes_cab_xl": {
      "type": "number",
      "default": 0,
      "description": "Cabinet size: XL (100+ sqft)"
    },
    "base_minutes_flat": {
      "type": "number",
      "default": 0,
      "description": "Used when rate_basis = 'flat' or 'per_unit' (then this is minutes per unit)."
    },
    "default_materials": {
      "type": "array",
      "description": "Inventory items typically pulled for this (sign_type \u00d7 action). Used to auto-fill the Materials picker.",
      "items": {
        "type": "string"
      }
    },
    "is_enabled": {
      "type": "boolean",
      "default": true
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "sign_type",
    "action"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__maintenanceactionrate_backend_only__" } },
    "read": { "user_condition": { "role": "__maintenanceactionrate_backend_only__" } },
    "update": { "user_condition": { "role": "__maintenanceactionrate_backend_only__" } },
    "delete": { "user_condition": { "role": "__maintenanceactionrate_backend_only__" } }
  }
}

{
  "name": "MaintenanceEquipment",
  "type": "object",
  "description": "Lifts, boom trucks, ladders, vehicles and tools available to the Sign Maintenance / Installation estimators, with rental or owned pricing, reach geometry and idle-running costs.",
  "properties": {
    "equipment_name": {
      "type": "string"
    },
    "equipment_type": {
      "type": "string",
      "enum": [
        "ladder",
        "scissor_lift",
        "boom_lift",
        "boom_truck",
        "scaffold",
        "truck",
        "car",
        "van",
        "flatbed",
        "hand_tool",
        "power_tool",
        "safety",
        "other"
      ],
      "default": "ladder"
    },
    "ownership": {
      "type": "string",
      "enum": [
        "owned",
        "rented"
      ],
      "default": "rented"
    },
    "max_height_feet": {
      "type": "number",
      "default": 0
    },
    "total_boom_height_feet": {
      "type": "number",
      "default": 0
    },
    "horizontal_boom_reach_feet": {
      "type": "number",
      "default": 0
    },
    "deployed_truck_width_feet": {
      "type": "number",
      "default": 0
    },
    "vertical_reach_safety_margin_feet": {
      "type": "number",
      "default": 2
    },
    "is_default_for_height": {
      "type": "boolean",
      "default": false
    },
    "default_height_min_feet": {
      "type": "number",
      "default": 0
    },
    "default_height_max_feet": {
      "type": "number",
      "default": 0
    },
    "idle_running_cost_per_hour": {
      "type": "number",
      "default": 0
    },
    "pricing_mode": {
      "type": "string",
      "enum": [
        "owned_flat",
        "per_hour",
        "per_day",
        "per_week",
        "per_month",
        "per_project_flat"
      ],
      "default": "per_day"
    },
    "cost_per_hour": {
      "type": "number",
      "default": 0
    },
    "cost_per_day": {
      "type": "number",
      "default": 0
    },
    "cost_per_week": {
      "type": "number",
      "default": 0
    },
    "cost_per_month": {
      "type": "number",
      "default": 0
    },
    "cost_flat": {
      "type": "number",
      "default": 0
    },
    "delivery_pickup_cost": {
      "type": "number",
      "default": 0
    },
    "mpg": {
      "type": "number",
      "default": 0
    },
    "fuel_type": {
      "type": "string",
      "enum": [
        "na",
        "gasoline",
        "diesel"
      ],
      "default": "na"
    },
    "rental_company": {
      "type": "string"
    },
    "notes": {
      "type": "string"
    },
    "is_active": {
      "type": "boolean",
      "default": true
    },
    "sort_order": {
      "type": "number",
      "default": 0
    }
  },
  "required": [
    "equipment_name",
    "equipment_type",
    "pricing_mode"
  ],
  "rls": {
    "create": { "user_condition": { "role": "__maintenanceequipment_backend_only__" } },
    "read": { "user_condition": { "role": "__maintenanceequipment_backend_only__" } },
    "update": { "user_condition": { "role": "__maintenanceequipment_backend_only__" } },
    "delete": { "user_condition": { "role": "__maintenanceequipment_backend_only__" } }
  }
}

{
  "name": "MaintenanceInventory",
  "type": "object",
  "description": "Materials catalog for the Sign Maintenance estimator, scoped by sign type, size and action, with size-tiered or per-unit pricing.",
  "properties": {
    "item_name": {
      "type": "string"
    },
    "applies_to_item_types": {
      "type": "array",
      "description": "Sign / service item types this material applies to. Empty array = applies to all.",
      "items": {
        "type": "string",
        "enum": [
          "flush_channel",
          "halo_channel",
          "raceway_channel",
          "capsule_logo",
          "dimensional_letters",
          "monument_sign",
          "pylon_sign",
          "post_and_panel"
        ]
      }
    },
    "applies_to_sizes": {
      "type": "array",
      "description": "Letter sizes (for channel/dimensional) AND cabinet sizes (for monument/pylon/P&P) this material applies to. Empty = all.",
      "items": {
        "type": "string",
        "enum": [
          "extra_small",
          "small",
          "medium",
          "large",
          "extra_large",
          "extra_extra_large",
          "cab_small",
          "cab_medium",
          "cab_large",
          "cab_extra_large"
        ]
      }
    },
    "applies_to_actions": {
      "type": "array",
      "description": "Maintenance actions this material applies to. Empty = all.",
      "items": {
        "type": "string",
        "enum": [
          "clean",
          "repaint",
          "led_retrofit",
          "replace_leds",
          "replace_power_supplies",
          "replace_fluorescent_tubes",
          "fix_electrical",
          "troubleshoot",
          "vinyl_replacement",
          "replace_face",
          "replace_returns",
          "replace_trim_cap",
          "reseal",
          "rewire",
          "replace_ballast",
          "replace_transformer",
          "replace_breaker",
          "replace_photocell",
          "replace_timer",
          "replace_disconnect"
        ]
      }
    },
    "inventory_entity": {
      "type": "string",
      "description": "Master Inventory entity that owns the linked resource and authoritative cost."
    },
    "inventory_item_id": {
      "type": "string",
      "description": "ID of the linked Master Inventory resource."
    },
    "inventory_item_name": {
      "type": "string",
      "description": "Cached display name of the linked Master Inventory resource."
    },
    "usage_basis": {
