      "type": "string",
      "enum": [
        "sign_ordinance",
        "permit_application",
        "zoning_code",
        "fee_schedule",
        "checklist",
        "legislative_record",
        "gis_resource",
        "portal_instruction",
        "other"
      ],
      "description": "Kind of source document."
    },
    "category": {
      "type": "string",
      "description": "Free-text category label for grouping (e.g. 'adopted_code', 'rewrite_draft', 'legislative_evidence')."
    },
    "official_url": {
      "type": "string",
      "description": "Exact official URL the source was retrieved from."
    },
    "online_form_url": {
      "type": "string",
      "description": "Online application/form portal URL when distinct from the official_url."
    },
    "archived_file_path": {
      "type": "string",
      "description": "Repository path to the archived file (e.g. public/permitting/sources/boone-ky/...)."
    },
    "archived_file_url": {
      "type": "string",
      "description": "Storage file_url for the archived copy when uploaded to app storage."
    },
    "file_hash_sha256": {
      "type": "string",
      "description": "SHA-256 hash of the archived file bytes."
    },
    "file_bytes": {
      "type": "number",
      "description": "Byte count of the archived file."
    },
    "http_outcome": {
      "type": "string",
      "description": "HTTP status / outcome of the retrieval (e.g. '200', '404', 'manual')."
    },
    "retrieval_timestamp": {
      "type": "string",
      "format": "date-time",
      "description": "When the source was retrieved/archived. Distinct from effective_or_adopted_date."
    },
    "document_revision_date": {
      "type": "string",
      "description": "Revision date printed on the document itself, when known."
    },
    "effective_or_adopted_date": {
      "type": "string",
      "description": "Official effective or adopted date of the content. Distinct from retrieval_timestamp."
    },
    "content_status": {
      "type": "string",
      "enum": [
        "unknown",
        "current",
        "historical",
        "draft",
        "proposed",
        "superseded"
      ],
      "default": "unknown",
      "description": "Whether current adoption is unknown or content is current, historical, draft, proposed, or superseded. Successful retrieval does not establish current authority."
    },
    "authority_confidence": {
      "type": "string",
      "enum": [
        "high",
        "medium",
        "low",
        "unverified"
      ],
      "default": "unverified",
      "description": "Confidence that this source is the authoritative current source for its subject."
    },
    "jurisdiction_scope": {
      "type": "string",
      "description": "Scope of applicability (e.g. 'unincorporated Boone County', 'Florence Main Street overlay', 'countywide right-of-way')."
    },
    "supersedes": {
      "type": "string",
      "description": "Reference to a source document this one supersedes, when verified."
    },
    "superseded_by": {
      "type": "string",
      "description": "Reference to a source document that supersedes this one, when verified."
    },
    "last_checked": {
      "type": "string",
      "format": "date-time",
      "description": "When the source was last checked against the official URL for changes."
    },
    "last_changed": {
      "type": "string",
      "format": "date-time",
      "description": "When the source content was last observed to have changed at the official URL."
    },
    "verification_status": {
      "type": "string",
      "enum": [
        "needs_verification",
        "verified",
        "historical",
        "gap_recorded"
      ],
      "default": "needs_verification",
      "description": "Human review status. 'gap_recorded' means no official source found and the gap is documented."
    },
    "reviewer": {
      "type": "string",
      "description": "Employee who last verified or reviewed this source."
    },
    "notes_gaps": {
      "type": "string",
      "description": "Explicit gaps, caveats, applicability notes, and supersession relationships."
    },
    "extracted_text": {
      "type": "string",
      "description": "Searchable extracted text from the archived file. For segmented extraction this preserves the initial inline preview; read physical pages through getPermittingSourceTextPages. Check text_extraction_state for scope and completeness."
    },
    "text_extraction_pinned": {
      "type": "boolean",
      "description": "Preserves staff-maintained text; both manual and automatic extraction must skip it."
    },
    "text_extraction_state": {
      "type": "object",
      "additionalProperties": true,
      "description": "Bounded deterministic text-extraction lease, retry state, page cursor, archive identity, and completeness. Text availability does not establish adopted authority."
    },
    "extracted_pages": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "page": {
            "type": "integer"
          },
          "text": {
            "type": "string"
          },
          "source_document_id": {
            "type": "string"
          },
          "source_sha256": {
            "type": "string"
          },
          "text_sha256": {
            "type": "string"
          },
          "method": {
            "type": "string"
          },
          "extracted_at": {
            "type": "string",
            "format": "date-time"
          },
          "truncated": {
            "type": "boolean"
          },
          "needs_ocr_review": {
            "type": "boolean"
          }
        }
      },
      "description": "Preserved initial physical PDF pages with extracted text, archive hash, parser method, and gaps. Later pages may live in immutable PermittingSourceTextSegment records; the committed cursor is in text_extraction_state. Original archive and review decisions remain intact."
    },
    "authority_review": {
      "type": "object",
      "additionalProperties": true,
      "description": "Version-bound staff review of an administrative source publisher, current-source evidence and explicitly quoted geographic scope. Never establishes adopted law or resolves a job address."
    },
    "authority_review_state": {
      "type": "object",
      "additionalProperties": true,
      "description": "Durable manual authority-review audit create/application receipt. Unknown creates reconcile without repeated writes."
    },
    "rule_import_state": {
      "type": "object",
      "additionalProperties": true,
      "description": "Source-wide candidate import reservation across all manual analysis runs. Uncertain creates retain their extraction key until reconciled; a fresh run cannot bypass the create intent."
    },
    "rule_extraction_state": {
      "type": "object",
      "additionalProperties": true,
      "description": "Manual selected-page rule extraction reservation and durable run identity. Independent of text/archive workers; unknown creates and LLM attempts are reconciled, never blindly repeated."
    },
    "derived_facts": {
      "type": "object",
      "additionalProperties": true,
      "description": "Structured facts derived from the source (fee amounts, permit exemptions, etc.)."
    },
    "authority_classification": {
      "type": "string",
      "enum": [
        "current_adopted",
        "draft_proposed",
        "comprehensive_rewrite",
        "narrow_amendment",
        "historical",
        "superseded",
        "application_form",
        "checklist",
        "fee_schedule",
        "administrative_guidance",
        "legislative_evidence",
        "effective_date_evidence",
        "unknown_review_required"
      ],
      "default": "unknown_review_required",
      "description": "Deterministic authority classification produced by the source classifier. Draft/comprehensive_rewrite classifications trigger rewrite protection via the authority gate."
    },
    "matched_signals": {
      "type": "array",
      "description": "Deterministic signals/evidence that led to the authority_classification.",
      "items": {
        "type": "string"
      },
      "default": []
    },
    "classified_at": {
      "type": "string",
      "format": "date-time",
      "description": "When the authority_classification was computed and persisted."
    },
    "ocr_evidence": {
      "type": "array",
      "maxItems": 5,
      "description": "Bounded append-only administrator-supplied OCR evidence. Each receipt is tied to verified PDF bytes and physical page, retained unreviewed, with method and content integrity hashes. Kept separate from extracted_text/pages and all authority reviews. Read through permittingSourceOcrEvidence; never substitute into approved regulations automatically.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "record_key": {
            "type": "string"
          },
          "source_document_id": {
            "type": "string"
          },
          "source_sha256": {
            "type": "string"
          },
          "archived_file_url": {
            "type": "string"
          },
          "file_bytes": {
            "type": "integer"
          },
          "page": {
            "type": "integer"
          },
          "text": {
            "type": "string",
            "maxLength": 30000
          },
          "text_sha256": {
            "type": "string"
          },
          "payload_sha256": {
            "type": "string"
          },
          "record_sha256": {
            "type": "string"
          },
          "method": {
            "type": "string"
          },
          "request_id": {
            "type": "string"
          },
          "extracted_at": {
            "type": "string",
            "format": "date-time"
          },
          "retained_at": {
            "type": "string",
            "format": "date-time"
          },
          "requested_by": {
            "type": "string"
          },
          "input_kind": {
            "type": "string",
            "enum": [
              "administrator_supplied_ocr"
            ]
          },
          "review_status": {
            "type": "string",
            "enum": [
              "unreviewed"
            ]
          }
        }
      }
    },
    "ocr_transcriptions": {
      "type": "array",
      "maxItems": 5,
      "description": "Append-only through the evidence handler: visual transcription candidates bound to a retained OCR record, archive hash, physical page and normalized excerpt regions. Always pending staff review. Original OCR and regulatory/source approvals remain unchanged.",
      "items": {
        "type": "object",
        "additionalProperties": true,
        "properties": {
          "record_key": {
            "type": "string"
          },
          "request_id": {
            "type": "string"
          },
          "source_document_id": {
            "type": "string"
          },
          "source_sha256": {
            "type": "string"
          },
          "archived_file_url": {
            "type": "string"
          },
          "file_bytes": {
            "type": "integer"
          },
          "page": {
            "type": "integer"
          },
          "ocr_record_key": {
            "type": "string"
          },
          "ocr_record_sha256": {
            "type": "string"
          },
          "render": {
            "type": "object",
            "additionalProperties": true
          },
          "spans": {
            "type": "array",
            "minItems": 1,
            "maxItems": 5,
            "items": {
              "type": "object",
              "additionalProperties": true
            }
          },
          "observation_kind": {
            "type": "string",
            "enum": [
              "agent_visual_transcription"
            ]
          },
          "coverage": {
            "type": "string",
            "enum": [
              "selected_excerpts_only"
            ]
          },
          "payload_sha256": {
            "type": "string"
          },
          "record_sha256": {
            "type": "string"
          },
          "submitted_by": {
            "type": "string"
          },
          "retained_at": {
            "type": "string",
            "format": "date-time"
          },
          "review_status": {
            "type": "string",
            "enum": [
              "pending_staff_review"
            ]
          }
        }
      }
    }
  },
